import{_ as a,c as t,a as s,o as i}from"./app-C_dHcy8Q.js";const o={};function l(n,e){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="http-adapter-generic" tabindex="-1"><a class="header-anchor" href="#http-adapter-generic"><span>HTTP Adapter (Generic)</span></a></h1><p>The <code>http-adapter</code> exposes one function <code>http.generic_invoke</code> that forwards a generic HTTP request and returns the response body (best-effort JSON passthrough).</p><p>Usage</p><ul><li>Function: <code>http.generic_invoke</code></li><li>Request schema: <code>{ method, url, headers, body }</code></li><li>Output views (pack example): <ul><li><code>json.view</code> to preview raw response</li><li><code>table.basic</code> to render array responses as a table</li></ul></li></ul><p>Examples</p><ul><li>List JSON array <ul><li>URL: https://example.com/api/items</li><li>Response: <code>[ { &quot;id&quot;: 1, &quot;name&quot;: &quot;foo&quot; }, { &quot;id&quot;: 2, &quot;name&quot;: &quot;bar&quot; } ]</code></li><li>The built-in <code>table.basic</code> view works directly with <code>transform.expr: &#39;$&#39;</code>.</li></ul></li><li>Nested data array <ul><li>Response: <code>{ &quot;data&quot;: { &quot;items&quot;: [ { &quot;id&quot;: 1 }, { &quot;id&quot;: 2 } ] } }</code></li><li>Update the view transform to <code>expr: &#39;$.data.items&#39;</code> or use <code>template</code>:</li></ul></li></ul><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">{</span>
<span class="line">  &quot;id&quot;: &quot;table&quot;,</span>
<span class="line">  &quot;renderer&quot;: &quot;table.basic&quot;,</span>
<span class="line">  &quot;transform&quot;: { &quot;expr&quot;: &quot;$.data.items&quot; }</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>Timeseries <ul><li>Response: <code>{ &quot;series&quot;: [ { &quot;name&quot;: &quot;cpu&quot;, &quot;data&quot;: [[1719916800000, 0.5], ...] } ] }</code></li><li>Add a chart view:</li></ul></li></ul><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">{</span>
<span class="line">  &quot;id&quot;: &quot;chart&quot;,</span>
<span class="line">  &quot;renderer&quot;: &quot;echarts.line&quot;,</span>
<span class="line">  &quot;transform&quot;: { &quot;expr&quot;: &quot;$.series&quot; }</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Notes</p><ul><li>The adapter does not transform JSON by itself. Packs (descriptors) can shape data for views via <code>outputs.views[].transform</code> (see <code>docs/ui-and-views.md</code>).</li><li>For authenticated APIs, set headers in the request (e.g., <code>Authorization</code>).</li><li>For large payloads, prefer <code>GET</code> or compressed responses; current timeout defaults to 15s.</li></ul><p>Built-in function (example)</p><ul><li>The HTTP adapter also exposes a convenience function: <ul><li><code>alertmanager.list_alerts</code>: map simple params <code>{ base_url, silenced?, inhibited?, active? }</code> to Alertmanager <code>GET /api/v2/alerts</code>.</li><li>A sample pack <code>packs/alertmanager</code> renders alerts as a table (columns: name, severity, status, startsAt, summary).</li><li>Usage flow: import <code>alertmanager.pack.tgz</code> → select <code>alertmanager.list_alerts</code> → fill base URL and filters → view table/json.</li></ul></li></ul>`,13)])])}const c=a(o,[["render",l]]),d=JSON.parse('{"path":"/http-adapter.html","title":"HTTP Adapter (Generic)","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1762002341000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"228147054e4f1a15cada6bb3a8af42c4128040fb","time":1762002341000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"chore: commit local changes"}]},"filePathRelative":"http-adapter.md"}');export{c as comp,d as data};
